-- 📚 꼭집 주거 사전 — 총자산 3.62억 · 자동차 기준 없음 · 매입 신혼·신생아Ⅱ(전세형) · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.1초 · 결과:
-- {"n": 22, "by_std": {"공공임대(6·10·50년)": 1, "매입임대": 20, "전세임대": 1}, "all_asset_anns": 203, "ex": ["SH_310653", "21390_부산광역시_사하구", "2015122300020873", "2015122300020841"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('n',(select count(distinct announcement_id) from e where asset_limit=362000000 and car_limit is null),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit=362000000 and car_limit is null group by 1)q),'all_asset_anns',(select count(distinct announcement_id) from e where asset_limit is not null),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=362000000 and car_limit is null order by 1 desc limit 4)q))j;
